+             SELECT 1 FROM section_groups sg JOIN group_members gm ON gm.group_id = sg.group_id
+             WHERE sg.section_id = s.id AND gm.user_id = $3 AND sg.deleted_at IS NULL AND gm.deleted_at IS NULL))
+         ORDER BY m.created_at DESC LIMIT $4`,
+        [binderId, pattern, userId, lim]
+      );
+      result.messages = rows.rows;
+    }
+
     return result;
   }

   async getBinder(binderId) {
     const binder = await BinderDAO.findById(pool, binderId);
     if (!binder) throw new NotFoundError('바인더를 찾을 수 없습니다');
     return binder;
   }

   async getJoinRequests(binderId, userId) {
     const member = await BinderDAO.getMember(pool, binderId, userId);
     if (!member || member.deleted_at || member.role > 1) throw new ForbiddenError('권한이 없습니다');
     return await BinderDAO.getPendingMembers(pool, binderId);
   }

   async approveJoinRequest(binderId, targetUserId, requesterId) {
     await withTransaction(async (client) => {
       const requester = await BinderDAO.getMember(client, binderId, requesterId);
       if (!requester || requester.deleted_at || requester.role > 1) throw new ForbiddenError('권한이 없습니다');
       await BinderDAO.addMember(client, binderId, targetUserId, 3);
       await BinderDAO.incrementMemberCount(client, binderId);
     });
     eventBus.emit('member:joined', { user_id: targetUserId, binder_id: binderId });
   }

   async rejectJoinRequest(binderId, targetUserId, requesterId) {
     const requester = await BinderDAO.getMember(pool, binderId, requesterId);
     if (!requester || requester.deleted_at || requester.role > 1) throw new ForbiddenError('권한이 없습니다');
     await BinderDAO.removePendingRequest(pool, binderId, targetUserId);
   }

   async updateNickname(binderId, userId, nickname) {
     await BinderDAO.updateNickname(pool, binderId, userId, nickname ?? null);
   }

-- 스키마 현실 매핑: 설계 스펙의 "binder_member_id → binder_members(id)" 는
--   binder_members 가 복합 PK(binder_id, user_id)·surrogate id 없음이므로 user_id → users(id)
--   로 매핑한다. 바인더 범위는 groups.binder_id 로 고정된다(그룹의 binder = 섹션의 binder).
-- updated_at: 설계 스케치엔 없으나 revoke tombstone delta pull(AC1·§7-A E항)이 delta cursor 에
--   의존하므로 Rally sync 규약(idx_*_sync ON (scope, updated_at))에 맞춰 포함한다.
-- ============================================================

DROP TABLE IF EXISTS section_groups CASCADE;
DROP TABLE IF EXISTS group_members  CASCADE;
DROP TABLE IF EXISTS groups         CASCADE;

CREATE TABLE groups (
  id          UUID        NOT NULL,
  binder_id   UUID        NOT NULL,
  name        TEXT        NOT NULL,
  -- 컬러 명찰 (식별 라벨). NULL=무색. 명찰 렌더용으로 binder 전 멤버 sync(로스터·링크는 스코프)
  color       TEXT,
  -- 생성자 (감사). 탈퇴 시 SET NULL. 사람 참조는 Rally 규약대로 users(id)
  created_by  UUID,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  PRIMARY KEY (id),
  CONSTRAINT fk_grp_binder  FOREIGN KEY (binder_id)  REFERENCES binders(id),
  CONSTRAINT fk_grp_creator FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX idx_groups_sync ON groups (binder_id, updated_at);

CREATE TABLE group_members (
  id          UUID        NOT NULL,
  group_id    UUID        NOT NULL,
  -- 설계 스펙 binder_member_id = (group.binder_id, user_id). Rally 규약대로 user_id → users(id)
  user_id     UUID        NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  PRIMARY KEY (id),
  CONSTRAINT fk_gm_group FOREIGN KEY (group_id) REFERENCES groups(id),
  CONSTRAINT fk_gm_user  FOREIGN KEY (user_id)  REFERENCES users(id)
);
-- 활성 멤버십 유일성 (soft delete 후 재추가 허용 — 부분 유니크, PG 인라인 불가)
CREATE UNIQUE INDEX uq_group_members_active ON group_members (group_id, user_id)
  WHERE deleted_at IS NULL;
-- revoke sync(E항): 자기 멤버십 delta·tombstone 을 user_id 스코프(접근필터 미적용)로 pull
CREATE INDEX idx_gm_user_sync ON group_members (user_id, updated_at);
-- 그룹 로스터 조회
CREATE INDEX idx_gm_group ON group_members (group_id) WHERE deleted_at IS NULL;

CREATE TABLE section_groups (
  id          UUID        NOT NULL,
  section_id  UUID        NOT NULL,
  group_id    UUID        NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  PRIMARY KEY (id),
  CONSTRAINT fk_sg_section FOREIGN KEY (section_id) REFERENCES sections(id),
  CONSTRAINT fk_sg_group   FOREIGN KEY (group_id)   REFERENCES groups(id)
);
-- 활성 grant 유일성 (soft delete 후 재연결 허용 — 부분 유니크)
CREATE UNIQUE INDEX uq_section_groups_active ON section_groups (section_id, group_id)
  WHERE deleted_at IS NULL;
-- 섹션별 grant 조회 (private 접근 판정 JOIN)
CREATE INDEX idx_sg_section ON section_groups (section_id) WHERE deleted_at IS NULL;
-- revoke sync(E항): binder 멤버십 스코프 delta (group→binder JOIN)
CREATE INDEX idx_sg_group_sync ON section_groups (group_id, updated_at);
